#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: RisingWave application secrets into IaC, then the QA cutover.
#
# Written 2026-10-15. Runs on WSL, not in a codespace: it needs the corp gh
# auth, the op-dev/op-qa AWS SSO profiles and the on-prem kubeconfigs.
#
# Ordering rule that the whole thing hangs on: apply.sh refuses a MISSING or
# EMPTY value, so an EXCLUDE_RE entry comes off LAST -- after the system
# exists, the secret exists and the key is non-empty. Un-excluding early fails
# the entire sync-hook Job, not just that one file.
#
# Split of duties, deliberately: terraform IMPORT runs locally because it only
# writes state, while terraform APPLY goes through Octopus because that is
# where this module's variables live. Never apply this module from a laptop.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=12

ENV_FILE="${ENV_FILE:-$HOME/.rw-qa-cutover.env}"

PIPE_REPO=variant-inc/risingwave-pipeline
ONPREM_REPO=variant-inc/iaac-risingwave-onprem
CICD_REPO=variant-inc/iaac-risingwave-cicd
POC_REPO=usxpressinc/risingwave-poc
KAFKA_REPO=variant-inc/ix-kafka-topics-users
DEV_PROFILE="${DEV_PROFILE:-}"
QA_PROFILE="${QA_PROFILE:-}"
QA_KUBE="$HOME/.kube/op-usxpress-qa-sso.yaml"
DEV_KUBE="$HOME/.kube/op-usxpress-dev-fresh.yaml"

# have CMD -- true when a binary exists. A missing tool is NOT a failing system.
have() { command -v "$1" >/dev/null 2>&1; }

# acct PROFILE WANT -- discriminates the three failures that look alike.
#
# Measured 2026-10-15: a MISSING profile was reported as an expired session, so
# the advice was "aws sso login --profile "$DEV_PROFILE"" for a profile that does not
# exist. A login can never fix that. Name the actual fault.
acct() {
  local p="$1" want="$2" got
  if ! aws configure list-profiles 2>/dev/null | grep -qxF "$p"; then
    warn "$p -> NOT CONFIGURED on this box. aws sso login cannot fix this."
    return 0
  fi
  got=$(aws sts get-caller-identity --profile "$p" --query Account --output text 2>&1 | head -1) || true
  case "$got" in
    "$want") say "  $p -> $got  OK" ;;
    [0-9]*)  warn "$p -> $got, wanted $want. Wrong profile for this step." ;;
    *)       warn "$p -> session invalid. Run: aws sso login --profile $p" ;;
  esac
}

# require_profile VAR_VALUE ACCOUNT -- true only when the profile is non-empty
# AND its live session is that account.
#
# An empty string is NOT an error to --profile: it selects the DEFAULT profile,
# which on this box is whichever account was last used. Assert before use.
require_profile() {
  local prof="$1" want="$2" got
  if [ -z "$prof" ]; then
    warn "no AWS profile resolved for account $want - nothing will be queried"
    return 1
  fi
  got=$(aws sts get-caller-identity --profile "$prof" --query Account --output text 2>/dev/null) || true
  if [ "$got" != "$want" ]; then
    warn "profile '$prof' is account ${got:-none}, wanted $want - refusing to continue"
    return 1
  fi
  return 0
}

# profile_for ACCOUNT -- prints the first configured profile whose LIVE session
# is that account, or nothing. Never guesses from the profile's name: op-dev,
# usx-dev and a dozen others are all plausible and only one is real.
profile_for() {
  local want="$1" p got
  for p in $(aws configure list-profiles 2>/dev/null); do
    got=$(aws sts get-caller-identity --profile "$p" --query Account --output text 2>/dev/null) || true
    if [ "$got" = "$want" ]; then printf '%s' "$p"; return 0; fi
  done
  return 0
}

banner "RisingWave: application secrets into IaC, then the QA cutover"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: tools and sessions"
say "Checking what this box can reach. Nothing is changed in this stage."
for t in gh aws kubectl jq terraform python3; do
  if have "$t"; then say "  $t  present"; else warn "$t MISSING"; fi
done
say ""
say "AWS sessions (expire often, hence this check first):"
acct "${DEV_PROFILE:-op-dev}" 700736442855
acct "${QA_PROFILE:-op-qa}"   527101283767
say ""
say "Resolving profile names by ACCOUNT, not by name. This calls STS once per"
say "configured profile, so it takes a moment."
DEV_PROFILE=$(profile_for 700736442855)
QA_PROFILE=$(profile_for 527101283767)
if [ -n "$DEV_PROFILE" ]; then
  say "  dev account 700736442855 -> profile '$DEV_PROFILE'"
  write_env DEV_PROFILE "$DEV_PROFILE"
else
  warn "no configured profile has a live session for dev 700736442855."
  warn "Log in to the right one, then re-run. Stages 4-5 need it."
  SKIPPED+=("an AWS profile with a live session for dev 700736442855")
fi
if [ -n "$QA_PROFILE" ]; then
  say "  QA account  527101283767 -> profile '$QA_PROFILE'"
  write_env QA_PROFILE "$QA_PROFILE"
else
  warn "no configured profile has a live session for QA 527101283767."
  SKIPPED+=("an AWS profile with a live session for QA 527101283767")
fi
say ""
if [ -f "$QA_KUBE" ]; then say "  QA kubeconfig present"; else warn "QA kubeconfig missing: $QA_KUBE"; fi
if [ -f "$DEV_KUBE" ]; then say "  dev kubeconfig present"; else warn "dev kubeconfig missing: $DEV_KUBE"; fi
say ""
note "terraform is needed for stages 4 and 5 only. Everything else works without it."
pause "Continue?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Merge PR #55: declare the five application secrets"
say "New file deploy/terraform/secrets-app.tf. manage_app_secrets defaults to"
say "FALSE, so merging is a no-op in every environment."
open_url "https://github.com/$ONPREM_REPO/pull/55"
step "Read all 233 lines. You have not seen them outside this PR."
step "Check: no 'import' blocks, every resource carries the count flag,"
step "       every version has ignore_changes = [secret_string]."
if confirm "Merge it now?"; then
  gh pr merge 55 --repo "$ONPREM_REPO" --squash --delete-branch || warn "merge failed, do it in the UI"
  say "Confirming the flag really defaults to false on main:"
  gh api "repos/$ONPREM_REPO/contents/deploy/terraform/secrets-app.tf?ref=main" -q .content \
    | base64 -d | grep -A3 'variable "manage_app_secrets"' || warn "could not read it back"
else
  SKIPPED+=("merge $ONPREM_REPO#55")
fi
pause "Next"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Octopus: the backend coordinates"
say "This module's backend is intentionally empty; deploy.ps1 fills it from"
say "S3_BUCKET / TF_STATE_KEY / AWS_DEFAULT_REGION. There is no .hcl in the"
say "repo, so stages 4 and 5 need those values from Octopus."
open_url "https://usxpress.octopus.app"
step "Find the RisingWave on-prem project, then Variables."
step "Read S3_BUCKET and TF_STATE_KEY for the Dev scope, then the QA scope."
warn "s3 ls is DENIED to op-*-platform-admin, so these cannot be discovered."
ask TF_REGION         "AWS_DEFAULT_REGION (usually us-east-2):"
ask DEV_S3_BUCKET     "Dev S3_BUCKET:"
ask DEV_TF_STATE_KEY  "Dev TF_STATE_KEY:"
ask QA_S3_BUCKET      "QA S3_BUCKET:"
ask QA_TF_STATE_KEY   "QA TF_STATE_KEY:"
write_env TF_REGION        "$TF_REGION"
write_env DEV_S3_BUCKET    "$DEV_S3_BUCKET"
write_env DEV_TF_STATE_KEY "$DEV_TF_STATE_KEY"
write_env QA_S3_BUCKET     "$QA_S3_BUCKET"
write_env QA_TF_STATE_KEY  "$QA_TF_STATE_KEY"
note "These are coordinates, not credentials. Safe in $ENV_FILE."
pause "Next"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Prepare a local terraform workspace (dev)"
say "Import only writes STATE, so it is safe to run here. Apply is NOT: this"
say "module's variables live in Octopus, so applies go through Octopus."
TFDIR=/tmp/rw-tf
rm -rf "$TFDIR"
gh repo clone "$ONPREM_REPO" "$TFDIR" -- --depth 1 -q || warn "clone failed"
if ! cd "$TFDIR/deploy/terraform" 2>/dev/null; then
  warn "no deploy/terraform in the clone - skipping this stage"
  SKIPPED+=("stage 4: terraform workspace")
else
say ""
say "Variables with no default, which terraform demands even for an import:"
python3 - <<'PY'
import re, pathlib
s = pathlib.Path("variables.tf").read_text()
blocks = re.findall(r'variable\s+"([^"]+)"\s*\{(.*?)\n\}', s, re.S)
# A variable whose DESCRIPTION contains the word "default" must not be
# mistaken for one that has a default. Match the argument, not the word.
need = [n for n, b in blocks if not re.search(r"^\s*default\s*=", b, re.M)]
print("  " + ("\n  ".join(need) if need else "(none)"))
pathlib.Path("/tmp/rw-need-vars.txt").write_text("\n".join(need) + ("\n" if need else ""))
PY
say ""
say "Read each from the Octopus Dev scope. Blank skips it (terraform will say"
say "if it really needed it)."
: > /tmp/rw-dev.auto.tfvars
while read -r v; do
  [ -z "$v" ] && continue
  sv="TFV_$(printf '%s' "$v" | tr -c '[:alnum:]_' _)"
  ask "$sv" "  $v ="
  eval "val=\${$sv:-}"
  [ -n "$val" ] && printf '%s = "%s"\n' "$v" "$val" >> /tmp/rw-dev.auto.tfvars
done < /tmp/rw-need-vars.txt
cp /tmp/rw-dev.auto.tfvars ./dev.auto.tfvars 2>/dev/null || true
say ""
say "vars captured: $(wc -l < ./dev.auto.tfvars 2>/dev/null || echo 0)"
note "dev.auto.tfvars is in a throwaway clone under /tmp and is never committed."
if have terraform; then
  say "Initialising against dev state..."
  terraform init -reconfigure -input=false \
    -backend-config="bucket=$DEV_S3_BUCKET" \
    -backend-config="key=$DEV_TF_STATE_KEY" \
    -backend-config="region=$TF_REGION" \
    -backend-config="encrypt=true" || warn "init failed - check the coordinates from stage 3"
  say "Backing up state BEFORE touching it:"
  terraform state pull > "$HOME/rw-dev-state-$(date +%Y%m%d-%H%M%S).json" \
    && say "  backup written to your home directory"
  say "Secrets already in dev state:"
  terraform state list 2>/dev/null | grep secretsmanager || say "  (none)"
else
  SKIPPED+=("stages 4-5: terraform is not installed on this box")
  warn "terraform absent - skipping the import stages"
fi
fi
pause "Next"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Dev: import the five secrets into state"
say "All five exist in the dev account and are absent from state. Without the"
say "import, the first apply with the flag on fails ResourceExistsException."
say ""
warn "Importing the VERSION matters as much as the secret. ignore_changes stops"
warn "an UPDATE, not a CREATE: an un-imported version would be created, which"
warn "overwrites the live credential with a placeholder."
say ""
if ! have terraform; then
  warn "terraform absent, nothing to do here"
elif ! require_profile "$DEV_PROFILE" 700736442855; then
  SKIPPED+=("stage 5: dev imports, no verified dev profile")
else
  PREFIX=op-usxpress-dev/risingwave
  for r in entity grafana kafka mongodb dex_entra_client_secret; do
    N="$PREFIX/$r"
    say "--- $r ---"
    if ! aws secretsmanager describe-secret --profile "$DEV_PROFILE" --secret-id "$N" \
         --query Name --output text >/dev/null 2>&1; then
      say "  not present in AWS, or no permission to describe it. Apply will create it."
      continue
    fi
    A=$(aws secretsmanager describe-secret --profile "$DEV_PROFILE" --secret-id "$N" \
          --query ARN --output text 2>/dev/null) || true
    V=$(aws secretsmanager describe-secret --profile "$DEV_PROFILE" --secret-id "$N" \
          --query VersionIdsToStages --output json 2>/dev/null \
          | jq -r 'to_entries[] | select(.value[] == "AWSCURRENT") | .key' | head -1) || true
    say "  ARN     $A"
    say "  version $V"
    if [ -z "$A" ] || [ -z "$V" ]; then
      warn "  could not resolve both - skipping, do not guess"
      SKIPPED+=("import dev $r")
      continue
    fi
    if confirm "  import $r (secret + version)?"; then
      terraform import -input=false -var="manage_app_secrets=true" \
        "aws_secretsmanager_secret.$r[0]" "$A" || warn "  secret import failed"
      terraform import -input=false -var="manage_app_secrets=true" \
        "aws_secretsmanager_secret_version.$r[0]" "$A|$V" || warn "  version import failed"
    fi
  done
  say ""
  say "Now the plan. What you want to see is NO changes to these five:"
  terraform plan -input=false -var="manage_app_secrets=true" -no-color \
    | tail -25 || warn "plan failed"
  warn "If the plan wants to REPLACE or UPDATE a secret_string, STOP. Restore"
  warn "from the backup in your home directory and tell me what it said."
fi
pause "Next"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Turn the flag on, per environment, via Octopus"
say "Terraform now knows about dev's five. Flip the variable so real deploys"
say "agree with what you just imported."
open_url "https://usxpress.octopus.app"
step "Project variables: add manage_app_secrets = true, scoped to Dev."
step "Deploy to Dev. Expect: no changes to the five secrets."
warn "A green Octopus deploy is not an apply. TfApply gates it; the proof is"
warn "the terraform_outputs.yml artifact on the deploy, not the green tick."
say ""
say "QA is different: it has only 'kafka' of the five, so a QA apply must"
say "CREATE four and would 409 on kafka. Import kafka into QA state first."
step "Re-run stages 4 and 5 with the QA coordinates and the op-qa profile,"
step "importing ONLY kafka, then scope manage_app_secrets = true to QA."
step "Deploy to QA. Expect: 4 created, kafka unchanged."
say ""
note "Prod needs NO import: none of the five exist there. Flag on, apply once."
pause "Next"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "QA: inject the three third-party values"
say "entity and grafana generated themselves. kafka, mongodb and dex hold"
say "UNVERIFIED_SET_THIS_VALUE until a human sets them."
say ""
say "mongodb: dev uses np_risingwave_service@mongodb.bjpgt.mongodb.net - an"
say "np (non-prod) user with no database in the URI, so QA can take the SAME"
say "string. The database name comes from config, not the URI."
say ""
if ! require_profile "$QA_PROFILE" 527101283767; then
  SKIPPED+=("stage 7: QA secret values, no verified QA profile")
elif confirm "Copy dev's MONGODB_CONNECTION_STRING into QA's secret?"; then
  U=$(kubectl --kubeconfig="$DEV_KUBE" -n app-risingwave get secret \
        etl-pipeline-credentials -o jsonpath='{.data.MONGODB_CONNECTION_STRING}' 2>/dev/null \
        | base64 -d) || true
  if [ -z "${U:-}" ]; then
    warn "could not read dev's value - check the dev kubeconfig"
    SKIPPED+=("QA mongodb secret value")
  else
    say "read dev's URI (${#U} chars, not printed)"
    printf '{"MONGODB_CONNECTION_STRING":"%s"}' "$U" > /tmp/rw-mongo.json
    if aws secretsmanager put-secret-value --profile "$QA_PROFILE" \
         --secret-id op-usxpress-qa/risingwave/mongodb \
         --secret-string "file:///tmp/rw-mongo.json" >/dev/null 2>&1; then
      say "  QA mongodb secret set"
    else
      warn "put-secret-value denied or the secret does not exist yet"
      SKIPPED+=("QA mongodb value: aws secretsmanager put-secret-value, see /tmp/rw-mongo.json")
    fi
    rm -f /tmp/rw-mongo.json
  fi
fi
say ""
say "dex: all environments share ONE Entra app registration (clientID"
say "e112d6ce...). A new environment is a redirect URI added to that app, not"
say "a new app, and the secret is a COPY."
step "Copy dev's dex_entra_client_secret value into QA's the same way."
say ""
say "Verifying nothing is left unset on QA:"
Q='.data | to_entries[] | select((.value|@base64d) | startswith("UNVERIFIED_")) | .key'
kubectl --kubeconfig="$QA_KUBE" -n app-risingwave get secret etl-pipeline-credentials \
  -o json 2>/dev/null | jq -r "$Q" || say "  (secret not readable yet)"
note "Any key listed above still holds the sentinel. Empty list is the pass."
pause "Next"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Make apply.sh refuse an UNVERIFIED_ value"
say "Today apply.sh rejects a MISSING or EMPTY value. The sentinel is neither,"
say "so it would sail straight through into a sink or a source definition."
say ""
warn "apply.sh lives in TWO repos. Only iaac-risingwave-cicd is BUILT."
warn "Two reviewed PRs once landed in the risingwave-pipeline copy and could"
warn "never run. Edit the shipped one."
open_url "https://github.com/$CICD_REPO/blob/main/build/apply.sh"
step "Find where it rejects a missing/empty value and add: reject any value"
step "beginning UNVERIFIED_, naming the variable in the error."
step "Open the PR against $CICD_REPO, not risingwave-pipeline."
say ""
say "Then the rollout chain, in order - each link is a separate trigger:"
step "1. merge, and let publish-applier.yml push risingwave/sql-applier"
step "2. bump applier_image in $POC_REPO .github/workflows/build-sql-image.yml"
step "   to the NEW digest. A pinned digest does nothing until the pin moves."
step "3. that merge runs build-sql-image, producing a new poc-pipeline digest"
step "4. promote dev:  gh workflow run promote.yml --repo $PIPE_REPO -f only=dev"
step "5. promote QA:   gh workflow run promote.yml --repo $PIPE_REPO -f only=qa"
say ""
note "Prove it at the destination, not with a green tick: the new applier logs"
note "a line the old one cannot. The hook Job is deleted on success AND on"
note "failure, so operationState.syncResult is the durable record."
pause "Next"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "values-qa.yaml: the Brand sink's config and credential"
say "QA is missing 11 config keys dev has. REAPPLY_CHANGED is correctly"
say "dev-only. These are the two the Brand sink needs:"
say ""
say "  MONGODB_DATABASE_BRAND:    rw_qa      <-- dev says rw_dev"
say "  MONGODB_COLLECTION_BRAND:  brands     <-- same on both"
say ""
warn "rw_qa is the ONLY thing separating QA's sink from dev's Atlas data."
warn "dev and QA share one non-prod Atlas user and the URI names no database,"
warn "so copying dev's rw_dev would make QA write into dev's collection and"
warn "nothing would error."
say ""
say "And the credential, which QA's ExternalSecret does not reference at all:"
say "  - secretKey: MONGODB_CONNECTION_STRING"
say "    path: risingwave/mongodb"
say "    property: MONGODB_CONNECTION_STRING"
say ""
step "Raise that as one PR against $PIPE_REPO on values-qa.yaml."
step "Do NOT drop the sink exclusion in the same PR - that is stage 12."
open_url "https://github.com/$PIPE_REPO/blob/master/deploy/chart/values-qa.yaml"
say ""
say "Also add, for PR #97's bootstrap hook (it 'required's the first one):"
say "  POSTGRES_HOST_NAME, POSTGRES_INTERNAL_PORT"
say ""
say "Current QA keys, for the diff:"
gh api "repos/$PIPE_REPO/contents/deploy/chart/values-qa.yaml?ref=master" -q .content 2>/dev/null \
  | base64 -d | grep -cE '^  [A-Z_]+:' | xargs -I{} echo "  {} config keys on QA (dev has 30)" || true
pause "Next"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Atlas: can the non-prod user write rw_qa?"
say "Nothing needs creating. MongoDB makes a database on first write, so the"
say "only question is whether np_risingwave_service is authorised for rw_qa"
say "and not just rw_dev."
open_url "https://cloud.mongodb.com"
step "Database Access -> np_risingwave_service -> Edit."
step "Check its roles: readWrite on rw_qa, or readWriteAnyDatabase."
step "If it is scoped to rw_dev only, add rw_qa. That is the whole job."
say ""
warn "2.8.2 DOES accept mongodb+srv even though the docs never say so, and"
warn "getent finding nothing for an SRV-only name is EXPECTED. Neither is"
warn "evidence of a broken endpoint."
if confirm "Is np_risingwave_service authorised for rw_qa?"; then
  say "  good - the sink can be un-excluded in stage 12"
else
  SKIPPED+=("Atlas: grant np_risingwave_service write on rw_qa")
  warn "recorded as outstanding; do not un-exclude the sink until it is done"
fi
pause "Next"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Employee: the Kafka topic, the grant, and the entities database"
say "Three things, none of which promotion can carry."
say ""
say "A. The QA Employee topic and its ACL, via $KAFKA_REPO:"
open_url "https://github.com/$KAFKA_REPO"
step "Add the QA Employee topic and grant the RisingWave service account."
warn "ix-kafka-topics-users PREPENDS dx__ and the environment, so a declared"
warn "prefix 'risingwave' renders as dx__qa_risingwave. The declared string is"
warn "not the literal ACL."
warn "Its DEV Octopus deploy is a REQUIRED CHECK before merge, and each"
warn "environment is still its own deploy afterwards."
say ""
say "B. PR #97 - the entities database as a sync hook:"
open_url "https://github.com/$PIPE_REPO/pull/97"
step "Review it. bootstrap.enabled defaults off; it is idempotent and never"
step "drops. It needs config.POSTGRES_HOST_NAME, which stage 9 added."
step "Merge, then set bootstrap.* in values-qa.yaml: database, role"
step "(rw_entity_app), schemas, publication, and the three key names."
say ""
say "C. The entity credential in QA's ExternalSecret:"
say "  POSTGRES_ENTITY_USER / POSTGRES_ENTITY_PASSWORD -> path risingwave/entity"
note "rw_entity_app is dev's role name, read from the live secret. The"
note "bootstrap hook and the secret MUST agree, or the password is right for a"
note "role that does not exist and every status field stays green."
say ""
say "D. The remaining config keys for Employee:"
say "  KAFKA_TOPIC_EMPLOYEE, POSTGRES_ENTITY_SCHEMA_EMPLOYEE,"
say "  POSTGRES_CDC_PUBLICATION, POSTGRES_CDC_SLOT,"
say "  MONGODB_DATABASE_EMPLOYEE (rw_qa), MONGODB_COLLECTION_EMPLOYEE (employees)"
pause "Next"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Drop the exclusions, ONE at a time"
say "This is last on purpose. apply.sh refuses a missing or empty value, and a"
say "refusal fails the whole sync-hook Job - not just the offending file."
say ""
say "QA's current EXCLUDE_RE excludes Template, shared, 300-Employee,"
say "100-Brand/400-sink.rw and 100-Brand/001-prescript.sql. That leaves the"
say "eight files QA applied on 2026-10-14."
say ""
say "Order, and what each one requires first:"
step "1. 100-Brand/400-sink.rw   <- stages 7, 9, 10 all complete"
step "2. 100-Brand/001-prescript.sql + 300-Employee  <- stage 11 complete"
say ""
warn "One per PR. Verify at the destination before the next one."
say ""
say "After each merge, promote and then check the LEDGER, not the sync status:"
note "  gh workflow run promote.yml --repo $PIPE_REPO -f only=qa"
note "  then query pipeline_applied on QA's postgres for the new filename"
say ""
say "Live QA applier state right now:"
kubectl --kubeconfig="$QA_KUBE" -n app-risingwave get job 2>/dev/null | head -5 \
  || say "  (QA not reachable)"
say ""
warn "A green Argo sync proves the hook ran, not that a file applied. Argo"
warn "deletes the Job on success and on failure alike, so the row in"
warn "pipeline_applied is the only durable evidence."
pause "Finish"

finish
